<script setup lang="ts">import {computed} from 'vue';import type {Risk} from '../types/domain';import {num} from '../utils/format';const props=defineProps<{risk:Risk}>();const bounds=computed(()=>{const lo=Math.min(props.risk.histogram[0].left,props.risk.deadline),hi=Math.max(props.risk.histogram.at(-1)!.right,props.risk.deadline);return {lo,hi:hi===lo?hi+1:hi,max:Math.max(...props.risk.histogram.map(b=>b.count))}});const x=(v:number)=>56+(v-bounds.value.lo)/(bounds.value.hi-bounds.value.lo)*790;const y=(v:number)=>290-v/bounds.value.max*240;</script><template><div class="histogram"><div class="plot-title"><strong>项目完工样本分布</strong><span>小时 / {{risk.samples}}次独立工期抽样</span></div><svg viewBox="0 0 900 345" role="img" aria-label="真实PERT项目完工样本分布"><g v-for="f in [0,.25,.5,.75,1]" :key="f"><line x1="56" x2="846" :y1="y(f*bounds.max)" :y2="y(f*bounds.max)" stroke="#d7d1c3"/><text x="44" :y="y(f*bounds.max)+4" text-anchor="end">{{Math.round(f*bounds.max)}}</text></g><rect v-for="(bin,i) in risk.histogram" :key="i" :x="x(bin.left)" :y="y(bin.count)" :width="Math.max(5,x(bin.right)-x(bin.left)-2)" :height="290-y(bin.count)" fill="#8f9077"><title>{{num(bin.left)}}—{{num(bin.right)}}小时：{{bin.count}}样本</title></rect><line :x1="x(risk.deadline)" :x2="x(risk.deadline)" y1="22" y2="295" stroke="#ac6c47" stroke-dasharray="5 3" stroke-width="2"/><text :x="Math.min(780,x(risk.deadline)+7)" y="18">截止 {{num(risk.deadline)}}h</text><text v-for="f in [0,.25,.5,.75,1]" :key="f" :x="x(bounds.lo+f*(bounds.hi-bounds.lo))" y="319" text-anchor="middle">{{num(bounds.lo+f*(bounds.hi-bounds.lo),1)}}</text></svg></div></template>